-- Display names for a set of patients, for the review screens.
-- Placeholders are generated by the caller, one per id (integers only).
SELECT
    P.InternalId                      AS INTERNALID,
    TRIM(P.FirstName)                 AS FIRSTNAME,
    TRIM(P.Surname)                   AS SURNAME,
    TRIM(ISNULL(P.PreferredName, '')) AS PREFERREDNAME
FROM Patients AS P
WHERE P.InternalId IN ({placeholders})
